import{_ as o,a0 as p,w as a,s as d,ao as e,I as l,x as s,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"端口转发简介 | LCTT x X-CMD","titleTemplate":false,"description":"端口转发简介 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"端口转发简介 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"端口转发简介 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20210928 What is port forwarding","title":"端口转发简介","tag":"202203","desc":""},"relativePath":"202203/20210928 What is port forwarding.md","filePath":"[post].md"}'),u={name:"202203/20210928 What is port forwarding.md"};function f(m,t,g,b,k,T){const n=p("Link");return a(),d("div",null,[t[38]||(t[38]=e('<h1 id="端口转发简介" tabindex="-1">端口转发简介 <a class="header-anchor" href="#端口转发简介" aria-label="Permalink to “端口转发简介”">​</a></h1><blockquote><p>本文介绍了几种端口转发最常见的使用场景。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/31/085031ezq55gmy15n5mgll.jpg" alt=""></p><p>端口转发就是把网络流量从一个网络监听者（称为一个“端口”）发送到另一个上，无论这两个端口是否属于同一台电脑。在这里，端口不是某个物理实体，而是一个监听网络活动的软件程序。</p><p>当流量被定向发往到某个特定的端口，它会先到达一个路由器或是防火墙，亦或是其他的网络程序。它最终收到的响应可能会根据它想要通讯的端口来定义。比如，当你使用端口转发时，你可以捕获到发往 8080 端口的流量，然后把它转发到 80 端口。对于接收信号的原端口来说，这个新的目标端口可能和它在同一台设备上，也可能是在另一台设备上。我们在很多情况下都会用到端口转发，实现的方式也有很多。本文将介绍其中最常见的几种使用场景。</p><h3 id="使用路由器来进行端口转发" tabindex="-1">使用路由器来进行端口转发 <a class="header-anchor" href="#使用路由器来进行端口转发" aria-label="Permalink to “使用路由器来进行端口转发”">​</a></h3><p>如果你在把服务器架设在家里，那么你通常是不需要转发端口的。你的家庭路由器（通常是你从<ruby>网络服务提供商<rt>Internet Service Provider</rt></ruby>（ISP）获得的 WiFi 设备）有一个内置的防火墙，它的作用是阻止外面的世界访问到你的家庭网络。通过使用端口转发，你可以允许某个指定端口的流量穿过路由器的防火墙，并发送到局域网中的某个指定的 IP 地址。</p>',7)),l("p",null,[t[1]||(t[1]=s("比如说，你架设了一个 ",-1)),r(n,{href:"https://opensource.com/alternatives/minecraft#minetest"},{default:i(()=>[...t[0]||(t[0]=[s("Minetest 服务",-1)])]),_:1}),t[2]||(t[2]=s("，并想要邀请你的朋友们来试试。为了让他们能够“穿过”你的路由器，从而到达这个 Minetest 服务，你必须把路由器上的某个端口转发到托管 Minetest 服务的电脑上。Minetest 服务默认运行在 30000 端口。你可以把路由器的 30000 端口转发到你的电脑的 30000 端口上，或者你也可以随便转发到一个更简单的端口上，这样玩家们会更容易记住它。我发现，当使用 30000 端口的时候，人们时常会少数几个 0（特别是没有逗号分隔符的帮助时），所以我一般使用路由器的 1234 端口，然后把它转发到我内部的 30000 端口。",-1))]),t[39]||(t[39]=l("p",null,"每个制造商的路由器接口都不一样，但是不管你用的是什么牌子的路由器，方法都是相同的。首先，你需要登录到你的路由器。",-1)),t[40]||(t[40]=l("p",null,"通常，路由器的 IP 地址和登录信息都会打印在路由器上，或者在是它的文档里。我有一个型号为 TP-Link GX90 的路由器，我在浏览器里访问 10.0.1.1 就可以登录它，但你的路由器可能是 192.168.0.1 或者其他的地址。",-1)),t[41]||(t[41]=l("p",null,[s("我的 GX90 路由器把端口转发功能称为“"),l("ruby",null,[s("虚拟服务器"),l("rt",null,"virtual servers")]),s("”，它是路由器的“NAT 转发”标签下的一个功能选项。NAT 的意思是 “"),l("ruby",null,[s("网络地址转换"),l("rt",null,"Network Address Translation")]),s("”。在其他路由器中，这个功能可能直接就叫做“端口转发”，或者叫“防火墙”、“服务”等。找到正确的功能选项可能需要花费一些时间，因此，你可能需要花点时间研究下你的路由器文档。")],-1)),l("p",null,[t[4]||(t[4]=s("当你找到了路由器的端口转发设置，添加一个新规则，命名一个外部端口（在我的例子中是 1234）和一个内部端口（30000）。把外部端口转发到内部端口上，而内部端口绑定在你想要大家访问的电脑的 IP 地址上。如果你需要一些查询本机 IP 地址的帮助，你可以阅读 Archit Modi 写的 《",-1)),r(n,{href:"https://opensource.com/article/18/5/how-find-ip-address-linux"},{default:i(()=>[...t[3]||(t[3]=[s("在 Linux 上如何查询本地 IP 地址",-1)])]),_:1}),t[5]||(t[5]=s("》。",-1))]),t[42]||(t[42]=l("p",null,[l("img",{src:"https://opensource.com/sites/default/files/uploads/router-port-forward.jpg",alt:"A sample port forwarding rule",title:"A sample port forwarding rule"})],-1)),t[43]||(t[43]=l("p",null,[l("em",null,"一个简单端口转发规则")],-1)),l("p",null,[t[7]||(t[7]=s("（图片提供者是 Seth Kenlon，遵循 ",-1)),r(n,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:i(()=>[...t[6]||(t[6]=[s("署名-相同方式共享 4.0 国际",-1)])]),_:1}),t[8]||(t[8]=s(" 协议）",-1))]),t[44]||(t[44]=l("p",null,"在这个例子中，访问家庭网络的 1234 端口的流量，都会被转发到了我的家庭服务器的 30000 端口上，后者的 IP 地址是 10.0.1.2。",-1)),t[45]||(t[45]=l("p",null,"在继续之前，先保存这个规则。",-1)),l("p",null,[t[12]||(t[12]=s("接下来，你需要知道你的家庭网络的公网 IP 地址是多少。你可以从 ",-1)),r(n,{href:"http://ifconfig.me"},{default:i(()=>[...t[9]||(t[9]=[s("ifconfig.me",-1)])]),_:1}),t[13]||(t[13]=s(" 或者 ",-1)),r(n,{href:"http://icanhazip.com"},{default:i(()=>[...t[10]||(t[10]=[s("icanhazip.com",-1)])]),_:1}),t[14]||(t[14]=s(" 上获得这个地址。你可以在浏览器中打开这两个网站的其中一个，也可以使用 ",-1)),r(n,{href:"https://opensource.com/article/20/5/curl-cheat-sheet"},{default:i(()=>[...t[11]||(t[11]=[s("curl",-1)])]),_:1}),t[15]||(t[15]=s(" 命令来获取到这个 IP。",-1))]),t[46]||(t[46]=e(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl ifconfig.me</span></span>
<span class="line"><span>93.184.216.34</span></span></code></pre></div><p>现在，你的朋友们就可以在 Minetest 客户端里输入 <code>169.169.23.49:1234</code>，加入你的 Minetest 服务器啦。</p><h3 id="使用防火墙来进行端口转发" tabindex="-1">使用防火墙来进行端口转发 <a class="header-anchor" href="#使用防火墙来进行端口转发" aria-label="Permalink to “使用防火墙来进行端口转发”">​</a></h3><p>系统管理员有时候需要转发访问服务器的流量。比如说，你可能想要接收来自 80 端口的流量，但是用户的服务却运行在 8065 端口。如果不进行端口转发的话，你的用户就不得不在输入浏览器的 URL 末尾，加上一个指定的端口号，例如 <code>example.com:8065</code>。大多数用户都不习惯于考虑端口的问题，所以你需要把访问网络通用的 80 端口的请求拦截下来，然后转发到你的网络应用的具体端口，这会给用户带来巨大的方便。</p>`,4)),l("p",null,[t[17]||(t[17]=s("你可以在服务器上使用 ",-1)),r(n,{href:"https://www.redhat.com/sysadmin/secure-linux-network-firewall-cmd"},{default:i(()=>[...t[16]||(t[16]=[s("firewall-cmd",-1)])]),_:1}),t[18]||(t[18]=s(" 来转发流量，它是访问 ",-1)),t[19]||(t[19]=l("code",null,"firewalld",-1)),t[20]||(t[20]=s(" 后台进程的",-1)),t[21]||(t[21]=l("ruby",null,[s("前端"),l("rt",null,"front-end")],-1)),t[22]||(t[22]=s("命令。",-1))]),t[47]||(t[47]=e(`<p>首先，设置好你想要转发的端口和协议：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd \\</span></span>
<span class="line"><span>    --add-forward-port \\</span></span>
<span class="line"><span>    port=80:proto=tcp:toport=8065</span></span></code></pre></div><p>为使修改永久生效，你需要加上 <code>--runtime-to-permanent</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --runtime-to-permanent</span></span></code></pre></div><h3 id="网络转发" tabindex="-1">网络转发 <a class="header-anchor" href="#网络转发" aria-label="Permalink to “网络转发”">​</a></h3><p>在网络传输中，除了端口转发外，还有其他种类的<ruby>转发<rt>forwarding</rt></ruby>形式，例如 IP 转发和代理等。当你熟悉了网络信息在路由时是怎么被处理的之后，你可以试试不同的转发形式（然后使用 <code>tcpdump</code> 或类似的工具）来看看哪一种最好、最符合你的需求。</p><hr>`,7)),l("p",null,[t[24]||(t[24]=s("via: ",-1)),r(n,{href:"https://opensource.com/article/21/9/what-port-forwarding"},{default:i(()=>[...t[23]||(t[23]=[s("https://opensource.com/article/21/9/what-port-forwarding",-1)])]),_:1})]),l("p",null,[t[29]||(t[29]=s("作者：",-1)),r(n,{href:"https://opensource.com/users/seth"},{default:i(()=>[...t[25]||(t[25]=[s("Seth Kenlon",-1)])]),_:1}),t[30]||(t[30]=s(" 选题：",-1)),r(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[26]||(t[26]=[s("lujun9972",-1)])]),_:1}),t[31]||(t[31]=s(" 译者：",-1)),r(n,{href:"https://github.com/lkxed"},{default:i(()=>[...t[27]||(t[27]=[s("lkxed",-1)])]),_:1}),t[32]||(t[32]=s(" 校对：",-1)),r(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[28]||(t[28]=[s("wxy",-1)])]),_:1})]),l("p",null,[t[35]||(t[35]=s("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[33]||(t[33]=[s("LCTT",-1)])]),_:1}),t[36]||(t[36]=s(" 原创编译，",-1)),r(n,{href:"https://linux.cn/"},{default:i(()=>[...t[34]||(t[34]=[s("Linux中国",-1)])]),_:1}),t[37]||(t[37]=s(" 荣誉推出",-1))])])}const P=o(u,[["render",f]]);export{C as __pageData,P as default};
